(function () {
  // Sady ikon: data + atributy obalového <svg> (klíče = hodnoty volby v Nastavení)
  const ZAKLAD = 'viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round"';
  const SADY = {
    barevne: [window.FC_IKONY_BAREVNE, ZAKLAD],
    duotone: [window.FC_IKONY_DUOTONE, ZAKLAD + ' fill="none" stroke-width="1.8"'],
    odznaky: [window.FC_IKONY_ODZNAKY, ZAKLAD + ' fill="none"'],
    plne:    [window.FC_IKONY_PLNE, ZAKLAD + ' fill="currentColor"'],
    carove:  [window.FC_IKONY, ZAKLAD + ' fill="none" stroke="currentColor" stroke-width="1.8"'],
    pixel: [window.FC_IKONY_PIXEL, 'viewBox="0 0 24 24" shape-rendering="crispEdges"'],
    pastel: [window.FC_IKONY_PASTEL, 'viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round"'],
    neon: [window.FC_IKONY_NEON, 'viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"'],
    rucne: [window.FC_IKONY_RUCNE, 'viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"'],
    hranate: [window.FC_IKONY_HRANATE, 'viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="square" stroke-linejoin="miter"'],
    komiks: [window.FC_IKONY_KOMIKS, 'viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round"'],
    retro: [window.FC_IKONY_RETRO, 'viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round"'],
    modre: [window.FC_IKONY_MODRE, 'viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round"'],
    tenke: [window.FC_IKONY_TENKE, 'viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1" stroke-linecap="round" stroke-linejoin="round"'],
    kruhy: [window.FC_IKONY_KRUHY, 'viewBox="0 0 24 24" fill="none" stroke-linecap="round" stroke-linejoin="round"']
  };
  const KLIC = 'webapp_forecast_ikony';
  let styl = 'barevne';
  try { const ulozeny = localStorage.getItem(KLIC); if (SADY[ulozeny]) styl = ulozeny; } catch (e) {}

  document.documentElement.dataset.ikony = styl;

  const svg = (nazev, s) => '<svg ' + SADY[s][1] + '>' + (SADY[s][0][nazev] || '') + '</svg>';

  // HTML ikony do textu: <i class="ik" data-ik="…"><svg…></i> – velikost 1.15em, čárová barva z okolního textu
  window.fcIkona = function (nazev, trida) {
    return '<i class="ik' + (trida ? ' ' + trida : '') + '" data-ik="' + nazev + '" aria-hidden="true">' + svg(nazev, styl) + '</i>';
  };

  function doplnVse() {
    document.querySelectorAll('i[data-ik]').forEach(function (el) {
      el.classList.add('ik');
      el.setAttribute('aria-hidden', 'true');
      el.innerHTML = svg(el.dataset.ik, styl);
    });
  }
  // Statické značky <i data-ik="…"></i> v HTML se doplní hned po načtení DOM
  document.addEventListener('DOMContentLoaded', doplnVse);

  // Ikona v zadané sadě bez ohledu na zvolený styl (náhled v Nastavení) – bez data-ik, přepnutí ji nepřepíše
  window.fcIkonaSady = function (nazev, sada) {
    return '<i class="ik" aria-hidden="true">' + svg(nazev, sada) + '</i>';
  };

  // Přepnutí sady (Nastavení): uložit, překreslit všechny ikony v DOM i v grafech
  window.fcIkonyStyl = function (novy) {
    if (novy === undefined) return styl;
    styl = SADY[novy] ? novy : 'barevne';
    try { localStorage.setItem(KLIC, styl); } catch (e) {}
    document.documentElement.dataset.ikony = styl;
    doplnVse();
    window.dispatchEvent(new Event('fc-ikona'));
  };

  // Ikona jako obrázek pro plátno (grafy). Vrací Image, nebo null, dokud se nenačte;
  // po načtení vyvolá na window událost 'fc-ikona', aby se grafy překreslily.
  const obrazky = new Map();
  window.fcIkonaObr = function (nazev, barva) {
    const klic = styl + '|' + nazev + '|' + barva;
    let img = obrazky.get(klic);
    if (!img) {
      img = new Image();
      img.onload = function () { window.dispatchEvent(new Event('fc-ikona')); };
      img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(
        svg(nazev, styl).replace('<svg ', '<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" color="' + barva + '" '));
      obrazky.set(klic, img);
    }
    return img.complete && img.naturalWidth ? img : null;
  };
})();
